	if v.cluster != "" && v.repo == "" {
		return errors.New("--cluster requires --repo")
	}
	if v.repo != "" && positional == "" && v.checkpoint == "" {
		return errors.New("--repo requires a checkpoint ID (positional or --checkpoint/-c)")
	}
